@dataclass(frozen=True, kw_only=True)
class StatusInfo:
    title: str
    node_count: int
    param_count: int
    texture_count: int
    dirty: bool
    rev: int
    # History belongs to the editor, so only this server query can answer it.
    undo_steps: int = 0
    redo_steps: int = 0
